func updateTodoByID(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	idStr := vars["id"]

	id, err := uuid.Parse(idStr)
	if err != nil {
		http.Error(w, fmt.Sprintf("Invalid ID: %s", err), http.StatusBadRequest)
		return
	}

	var updateTodo Todo
	err = json.NewDecoder(r.Body).Decode(&updateTodo)
	if err != nil {
		http.Error(w, fmt.Sprintf("Error decoding todo: %s", err), http.StatusBadRequest)
		return
	}

	for i, todo := range todos {
		if todo.ID == id {
			todos[i] = updateTodo
			t := map[string]interface{}{
