func (t *Todo) MarshalJSON() ([]byte, error) {
	// create a struct to hold the json data
	type todoJSON Todo

	// marshal the todo into json format
	tJSON := todoJSON(*t)
	return json.Marshal(tJSON)
}

// UnmarshalJSON implements the json.Unmarshaler interface for Todo
func (t *Todo) UnmarshalJSON(data []byte) error {
	// create a struct to hold the json data
	type todoJSON Todo

	// unmarshal the json data into the todo struct
	err := json.Unmarshal(data, &tJSON)
	if err != nil {
		return fmt.Errorf("unmarshal todo from json: %w", err)
	}
	// copy the unmarshalled data to the todo struct
	t.ID = int(tJSON.ID)
	t.Title = tJSON.Title
	t.Completed = tJSON.Completed
	return nil
}

